Command: app_data theme.get
Exit code: 0 (structured app-data runtime)

stdout:
/* VELVET CASKET (theme author guide v1.5, contract 1)
   One idea: every container is a coffin. Messages stand as upright coffins with a finial on the
   head, the message box is a coffin laid on its side, Home widgets are a row of coffins, dialogs are
   coffin lids, buttons are coffin tags, avatars are mourning cameos, and an iron cemetery fence runs
   under the top bar.
   Day  = PASTEL GOTH: lilac, mint, baby pink, thick black sticker outlines, bats and bow-skulls.
   Night = TRADITIONAL GOTH: black and oxblood velvet, antique silver trim, iron crosses, candlelight. */

:root{
  --mari-tokens-version:1;
  /* coffin geometry (px so the shape survives any height) */
  --vc-head:22px;   /* how far the head is cut in from each side */
  --vc-sh:22px;     /* how far down the shoulders sit */
  --vc-foot:14px;   /* how far the foot tapers in */
  --vc-bw:2px;      /* outline thickness */
  --vc-coffin:polygon(var(--vc-head) 0,calc(100% - var(--vc-head)) 0,100% var(--vc-sh),calc(100% - var(--vc-foot)) 100%,var(--vc-foot) 100%,0 var(--vc-sh));
  --vc-coffin-in:polygon(calc(var(--vc-head) - 1px) 0,calc(100% - var(--vc-head) + 1px) 0,100% calc(var(--vc-sh) - 1px),calc(100% - var(--vc-foot)) 100%,var(--vc-foot) 100%,0 calc(var(--vc-sh) - 1px));
  /* coffin on its side: head on the left, foot on the right */
  --vc-coffin-side:polygon(0 12px,30px 0,calc(100% - 8px) 6px,100% 50%,calc(100% - 8px) calc(100% - 6px),30px 100%,0 calc(100% - 12px));
  /* coffin tag for buttons and pills */
  --vc-tag:polygon(8px 0,calc(100% - 8px) 0,100% 50%,calc(100% - 8px) 100%,8px 100%,0 50%);

  --vc-blackletter:"UnifrakturCook","Old English Text MT",serif;
  --vc-serif:"EB Garamond",Garamond,"Times New Roman",serif;
  --vc-plate:"Cormorant SC","EB Garamond",serif;

  --radius:2px;
  --mari-font-ui:var(--vc-serif);
  --mari-font-heading:var(--vc-blackletter);
  --mari-font-chat:var(--vc-serif);
  --ov-serif:var(--vc-blackletter);
  --mari-chat-font-size:17px;
  --mari-chat-line-height:1.6;
  --mari-message-measure:72ch;
  --mari-paragraph-gap:0.8em;
  --mari-dialogue-weight:500;
  --mari-text-outline:0;
  --mari-min-ui-text:12px;
  --mari-toast-font-size:1rem;
  --mari-selected-tint:var(--primary);
  --mari-msg-head-rule:var(--vc-head-rule);
  --mari-home-art:none;
  --mari-home-widget-radius:0;
  --mari-home-widget-border-width:0;
  --mari-home-widget-font:var(--vc-serif);
  --mari-home-widget-title-font:var(--vc-blackletter);
  --mari-home-widget-title-size:1.6rem;
  --mari-home-widget-eyebrow-size:0.8125rem;
  --mari-home-widget-text-size:0.9375rem;
  --mari-home-widget-action-size:0.9375rem;
  --mari-home-shortcut-size:1rem;
  --mari-top-bar-plate-radius:0;
  --mari-composer-placeholder:"Whisper into the dark...";
  --mari-chat-wash:none;
  --mari-chat-row-art-opacity:0;
  --marinara-theme-accent-pulse:none;
  --glow-primary:transparent; --glow-accent:transparent;
  --mari-chat-column:46rem;
  --mari-art-saturation-1:28%; --mari-art-saturation-2:24%;
  --mari-pinned-speaker:on;
  --mari-phone-avatar:hidden;
}

/* ── NIGHT · traditional goth ─────────────────────────────── */
:root,:root[data-theme="dark"]{
  --vc-ground:#07090b; --vc-ink:#efe6e8; --vc-mute:#bfaeb5; --vc-faint:#9a8a91;
  --vc-hair:rgba(185,170,180,.28);
  --vc-trim:#9a8f99;              /* antique silver outline */
  --vc-lining:#0a1017;            /* coffin lining under the velvet */
  --vc-lining-user:#0d151d;
  --vc-velvet:url("theme:velvet-tile.webp");
  --vc-panel:rgba(8,12,16,.92);
  --vc-bar:#070b0e;
  --vc-accent:#215fa3;            /* oxblood */
  --vc-accent-ink:#a7ccf1;        /* readable crimson for text on black */
  --vc-gold:#dcb874;              /* candle gold */
  --vc-finial:url("theme:or-cross.webp");
  --vc-finial-user:url("theme:or-rose.webp");
  --vc-finial-latest:url("theme:or-candle.webp");
  --vc-crest:url("theme:or-crest.webp");
  --vc-scene-break:url("theme:or-fleur.webp");
  --vc-fence:url("theme:fence-night.svg");
